document.querySelectorAll('[data-board]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.board;document.querySelectorAll('[data-board]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));window.recorderDesign.setView('inside');window.recorderDesign.product.selectBoard(id);document.getElementById('board-hint').textContent=`已選取 ${id} 板件，3D 中以綠色標示；側板圖左緣為後緣，尺寸為孔心位置。`;document.getElementById('stage').scrollIntoView({behavior:'smooth',block:'center'});}));